sys_ux_client_script.script:
/**
* @param {Object} params
* @param {Object} params.api
* @param {Object} params.helpers
* @returns {string} A formatted query string containing KPI short descriptions.
*/
function evaluateProperty({ api, helpers }) {
    console.log('Function called properly');

    // Check if data exists
    if (!api.data.sam_walk_value_builder_1.output.standard_software_requests) {
        console.error("Error: KPI data is missing or undefined");
        return "";  // Return empty string to prevent errors
    }

    const kpi = api.data.sam_walk_value_builder_1.output.system_integrations;
    console.log('KPI values returned:', kpi);

    // Extract first three words from each KPI use case
    const output = kpi
        .map(record => record.short_description.split(/\s+/).join(' ')) // Ensure only first 3 words
        .filter(value => value && value.trim().length > 0); // Remove empty values

    console.log("Extracted KPI short descriptions:", output);

    if (output.length > 0) {
        // Join the short descriptions with commas
        // Depending on your query format requirements, you might need to adjust this:
        const query = `short_descriptionIN${output.join(',')}`;

        console.log("Final query string:", query);
        return query;
    }

    // Return empty string if no KPIs found
    return "";
}
